'use strict';
// Probability target: precipitation >=50 mm in a specific three-hour window.
// This is an ensemble exceedance frequency, NOT personal injury or street inundation probability.
const V18RAIN={cache:new Map(),pending:new Map(),errors:new Map(),maxAge:30*60*1000};
const V18RAIN_MODEL='icon_global';
const V18RAIN_SOURCE='https://open-meteo.com/en/docs/ensemble-api';
const V18RAIN_THRESHOLD_SOURCE='https://www.szlh.gov.cn/zmhd/wdzsk/content/post_12722512.html';
function v18RainLocation(p){const point=vResolve(p?.destination||V5.weatherPlace);if(!point||point.regionOnly||![point.lat,point.lon].every(Number.isFinite))return null;return point}
function v18RainKey(point){return point.lat.toFixed(4)+','+point.lon.toFixed(4)}
function v18RainWindow(time,now=new Date()){const d=time?v11Date(time):now;if(!Number.isFinite(d.getTime()))return null;const start=Math.floor(d.getTime()/3600000)*3600000,end=start+3*3600000;return {start,end,times:[1,2,3].map(n=>new Date(start+n*3600000+8*3600000).toISOString().slice(0,16))}}
function v18ComputeRain(data,window){if(!window||data?.hourly_units?.precipitation!=='mm'||!Array.isArray(data?.hourly?.time))return null;const h=data.hourly,indices=window.times.map(t=>h.time.indexOf(t));if(indices.some(i=>i<0))return null;const keys=Object.keys(h).filter(k=>/^precipitation(?:_member\d+)?$/.test(k)),totals=keys.map(k=>indices.map(i=>h[k]?.[i])).filter(a=>a.every(n=>typeof n==='number'&&Number.isFinite(n)&&n>=0)).map(a=>a.reduce((s,n)=>s+n,0));if(totals.length<10||totals.length<keys.length*.8)return null;const count=totals.filter(n=>n>=50).length,severe=totals.filter(n=>n>=100).length;return {count,severe,n:totals.length,totalMembers:keys.length,percent:100*count/totals.length,severePercent:100*severe/totals.length,window,model:V18RAIN_MODEL}}
function v18ProbabilityTier(percent){if(percent<10)return {name:'较低',color:'gray',advice:'强降雨模型信号较少，保留雨具并避开已有封闭或积水区段。'};if(percent<30)return {name:'需关注',color:'orange',advice:'预留调整行程的时间，减少经过低洼路段。'};if(percent<60)return {name:'较高',color:'orange',advice:'非必要户外行程建议延后，必要事项优先远程办理。'};return {name:'高',color:'red',advice:'建议延后非必要出行，选择室内安全场所，遵从官方管制。'}}
function v18RainResult(p,now=new Date()){if((p?.mode||V2.mode)==='history')return {reason:'2023年当时的集合预报成员未归档，历史概率不补算。'};if(p?.probabilitySnapshot)return {...p.probabilitySnapshot,archived:true};const point=v18RainLocation(p);if(!point)return {reason:'该地点缺少具体坐标，无法计算地点天气概率。'};const key=v18RainKey(point),entry=V18RAIN.cache.get(key);if(!entry)return {reason:V18RAIN.pending.has(key)?'集合天气预报正在加载…':V18RAIN.errors.get(key)||'查询行程或刷新概率后显示。',point};if(now.getTime()-Date.parse(entry.fetched)>V18RAIN.maxAge)return {reason:'模型资料已超过30分钟，请刷新概率。',point};const window=v18RainWindow(p?.planned,now),r=v18ComputeRain(entry.data,window);if(!r)return {reason:!window?'出发时间无效。':window.times.some(t=>!entry.data.hourly.time.includes(t))?'出发时段不在这份预报覆盖范围内。':'该时段有效预报成员不足，暂无法计算。',point};return {...r,point,fetched:entry.fetched}}
function v18RainPanel(p){const r=v18RainResult(p),tier=r.n?v18ProbabilityTier(r.percent):null;return `<div class="v18rain"><b>强降雨概率（模型估算）${r.n?'：'+r.percent.toFixed(1)+'%':''}</b>${tier?` <span class="tag ${tier.color}">${tier.name}</span><small>模型估算 · 3小时降水≥50mm · ${esc(r.point.name)}</small><p>${tier.advice}</p>`:`<p>${esc(r.reason)}</p>`}${(p?.mode||V2.mode)!=='history'?`<button type="button" class="linkbutton" data-v18-rain="refresh" data-value="${esc(p?.id||'weather')}">刷新概率</button>`:''}<details><summary>查看概率计算、等级与数据来源</summary><p>计算的是所示地点出发所在整点起的3小时强降雨的模型发生比例，不是沿线积水、受伤或事故的概率。官方停运、封闭及避险要求优先于本估算；0%表示本次模型成员未预测该阈值，不表示安全。</p>${r.n?`<p>计算时段：${esc(dateText(new Date(r.window.start).toISOString()))}—${esc(dateText(new Date(r.window.end).toISOString()))}（北京时间）。按小时数据，从出发所在整点开始累计3小时；不是逐分钟预报。</p><p>P = 达标成员数 / 有效成员数 × 100% = ${r.count} / ${r.n} × 100% = ${r.percent.toFixed(1)}%。每个成员累加这3个小时的降水；无数据的成员不计入。3小时≥100mm的成员占比：${r.severePercent.toFixed(1)}%。</p><p>模型：DWD ICON Global EPS；有效成员 ${r.n}/${r.totalMembers}；刷新时间 ${esc(dateText(r.fetched))}（非模型发布时间）。预报使用模型网格，不代表街角实测。尚未完成深圳本地概率校准。</p>`:''}<table><tr><th>模型概率</th><th>提示等级</th><th>安排建议</th></tr><tr><td>0% ≤ P &lt; 10%</td><td>较低</td><td>保留雨具，避开已封闭区段</td></tr><tr><td>10% ≤ P &lt; 30%</td><td>需关注</td><td>预留调整时间，避开低洼路段</td></tr><tr><td>30% ≤ P &lt; 60%</td><td>较高</td><td>延后非必要户外行程</td></tr><tr><td>60% ≤ P ≤ 100%</td><td>高</td><td>优先室内安排，遵从官方管制</td></tr></table><p>概率分级为本 Demo 的产品规则，不是官方预警等级。50mm/3小时和100mm/3小时参考深圳暴雨橙色与红色预警的降水条件；模型概率不会自动发布官方预警。</p><p><a href="${V18RAIN_SOURCE}" target="_blank" rel="noopener">Open-Meteo集合预报说明</a> · <a href="${V18RAIN_THRESHOLD_SOURCE}" target="_blank" rel="noopener">罗湖暴雨预警含义（阈值参考）</a></p><p>降雨量描述一段时间内落下的雨水；道路积水还受地形、汇水和排水能力影响，因此不能由雨量直接推算水深。</p></details></div>`}
async function v18LoadRain(point,force=false){if(!point)return;const key=v18RainKey(point),cached=V18RAIN.cache.get(key);if(V18RAIN.pending.has(key))return V18RAIN.pending.get(key);if(!force&&cached&&Date.now()-Date.parse(cached.fetched)<V18RAIN.maxAge)return;const promise=(async()=>{try{const url=`https://ensemble-api.open-meteo.com/v1/ensemble?latitude=${point.lat}&longitude=${point.lon}&hourly=precipitation&models=${V18RAIN_MODEL}&forecast_days=3&timezone=Asia%2FShanghai`;const res=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error('集合天气服务暂时不可用，请稍后刷新。');const data=await res.json();if(data.error||!data.hourly||data.hourly_units?.precipitation!=='mm')throw Error('天气服务返回的数据不完整。');V18RAIN.cache.set(key,{data,fetched:new Date().toISOString()});V18RAIN.errors.delete(key)}catch(err){V18RAIN.errors.set(key,'集合天气查询未成功，当前不显示概率。')}finally{V18RAIN.pending.delete(key);if(typeof v19CaptureJourneys==='function')v19CaptureJourneys();if(V2.mode==='now')vRender()}})();V18RAIN.pending.set(key,promise);return promise}
const v18AddPlanBase=vAddPlan;vAddPlan=async function(){await v18AddPlanBase();if(V2.mode==='now'){const points=new Map(v11Group().map(p=>v18RainLocation(p)).filter(Boolean).map(p=>[v18RainKey(p),p]));await Promise.all([...points.values()].map(p=>v18LoadRain(p)))}};
const v18WeatherBase=vFetchWeather;vFetchWeather=async function(){await v18WeatherBase();if(V2.mode==='now'&&V2.weather)await v18LoadRain(v18RainLocation(null))};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v18-rain]');if(!b)return;const p=V2.plans.find(p=>p.id===b.dataset.value);if(V2.mode==='history')return;const point=v18RainLocation(p);if(!point)return toast('请填写可匹配到具体坐标的地点');if(p)delete p.probabilitySnapshot;v18LoadRain(point,true);vRender()});
const v18SnapshotBase=vSnapshot;vSnapshot=function(p){const s=v18SnapshotBase(p);s.rainProbabilities=(s.plans||[]).map(plan=>({planId:plan.id,result:v18RainResult(plan)}));return s};
const v18ExportBase=vExportParts;vExportParts=function(s,c){const parts=v18ExportBase(s,c);if(c.weather||c.risks)parts.push({title:'强降雨概率与计算范围',text:(s.rainProbabilities||[]).map(({planId,result:r})=>r.n?`${r.point.name}：3小时降水≥50mm模型概率${r.percent.toFixed(1)}%；${r.count}/${r.n}成员；时段${dateText(new Date(r.window.start).toISOString())}—${dateText(new Date(r.window.end).toISOString())}；刷新${dateText(r.fetched)}。不表示沿线积水或事故概率。模型来源${V18RAIN_SOURCE}`:r.reason).join('\n')||'此次快照未包含集合预报结果。'});return parts};
// Complete English copy for the calculation pane, retaining technical semantics.
const v18RainChinese=v18RainPanel;v18RainPanel=function(p){if(V5.profile.language!=='English')return v18RainChinese(p);const r=v18RainResult(p),tier=r.n?v18ProbabilityTier(r.percent):null;return `<div class="v18rain"><b>Heavy-rain probability (model estimate)${r.n?': '+r.percent.toFixed(1)+'%':''}</b>${tier?` <span class="tag ${tier.color}">${v18English(tier.name)}</span><small>Model estimate · 3-hour precipitation ≥50mm · ${esc(r.point.name)}</small><p>${v18English(tier.advice)}</p>`:`<p>${v18English(r.reason)}</p>`}${(p?.mode||V2.mode)!=='history'?`<button type="button" class="linkbutton" data-v18-rain="refresh" data-value="${esc(p?.id||'weather')}">Refresh probability</button>`:''}<details><summary>Probability method, levels and sources</summary><p>This measures the share of ensemble forecasts predicting at least 50mm of precipitation in the specified three-hour window. It does not measure street flooding, injury or accident probability. Official restrictions take precedence. A 0% estimate is not a safety guarantee.</p>${r.n?`<p>Window: ${esc(dateText(new Date(r.window.start).toISOString()))}—${esc(dateText(new Date(r.window.end).toISOString()))}. The window starts at the full hour containing departure; this is an hourly estimate, not a minute-by-minute forecast.</p><p>P = threshold-exceeding members / valid members × 100% = ${r.count} / ${r.n} × 100% = ${r.percent.toFixed(1)}%. Each member sums three preceding-hour precipitation values. Incomplete members are excluded. Members predicting ≥100mm: ${r.severePercent.toFixed(1)}%.</p><p>Model: DWD ICON Global EPS. Valid members: ${r.n}/${r.totalMembers}. Retrieved: ${esc(dateText(r.fetched))}, not the model issue time. Grid forecasts are not street-level observations. Local probability calibration has not been completed.</p>`:''}<table><tr><th>Estimate</th><th>Level</th><th>Advice</th></tr><tr><td>0% ≤ P &lt; 10%</td><td>Lower</td><td>Carry rain protection; avoid closures</td></tr><tr><td>10% ≤ P &lt; 30%</td><td>Attention</td><td>Allow changes; avoid low-lying roads</td></tr><tr><td>30% ≤ P &lt; 60%</td><td>Elevated</td><td>Postpone non-essential outdoor travel</td></tr><tr><td>60% ≤ P ≤ 100%</td><td>High</td><td>Prefer indoor plans; follow restrictions</td></tr></table><p>These probability bands are demo product rules, not official warning levels. The rainfall thresholds reference Shenzhen warning criteria; the model does not issue official warnings.</p><p><a href="${V18RAIN_SOURCE}" target="_blank" rel="noopener">Open-Meteo ensemble documentation</a> · <a href="${V18RAIN_THRESHOLD_SOURCE}" target="_blank" rel="noopener">Shenzhen threshold source (Chinese)</a></p><p>Rainfall alone cannot determine standing-water depth. Terrain, runoff and drainage also matter.</p></details></div>`};
